ALTER TABLE public.reviews ADD COLUMN source text NOT NULL DEFAULT 'raj' CHECK (source IN ('raj', 'google')), ADD COLUMN featured_home boolean NOT NULL DEFAULT false;
CREATE OR REPLACE VIEW public.reviews_public WITH (security_invoker = true) AS SELECT id, product_id, customer_name, rating, title, comment, verified_purchase, helpful_count, founder_response, founder_responded_at, created_at, photo_url, source, featured_home FROM public.reviews WHERE status = 'approved';
GRANT SELECT ON public.reviews_public TO anon, authenticated;
GRANT ALL ON public.reviews_public TO service_role;
CREATE OR REPLACE FUNCTION public.get_review_stats(_product_id text DEFAULT 'nexus') RETURNS TABLE(total bigint, average numeric, c5 bigint, c4 bigint, c3 bigint, c2 bigint, c1 bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT COUNT(*)::bigint, COALESCE(ROUND(AVG(rating)::numeric, 2), 0), COUNT(*) FILTER (WHERE rating = 5)::bigint, COUNT(*) FILTER (WHERE rating = 4)::bigint, COUNT(*) FILTER (WHERE rating = 3)::bigint, COUNT(*) FILTER (WHERE rating = 2)::bigint, COUNT(*) FILTER (WHERE rating = 1)::bigint FROM public.reviews WHERE product_id = _product_id AND status = 'approved' AND source = 'raj'; $$;
CREATE OR REPLACE FUNCTION public.review_source_guard() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $$ BEGIN IF NEW.source = 'google' THEN NEW.verified_purchase := false; END IF; RETURN NEW; END; $$;
CREATE TRIGGER review_source_guard BEFORE INSERT OR UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.review_source_guard();